    test('use attachment for large files', async () => {
        const rootDir = path.resolve(__dirname, 'apps', 'large')
        const staticDir = path.join(rootDir, 'dist', 'static')
        if (fs.existsSync(staticDir)) {
            fs.rmSync(staticDir, { recursive: true, force: true })
        }
        FileSystem.ensureDirSync(fs, staticDir)
        const largeFilePath = path.join(staticDir, 'large.js')
        const largeContent = 'A'.repeat(4194305)
        fs.writeFileSync(largeFilePath, largeContent, 'utf-8')

        const loggerWarnings: string[] = []
        const project = createProject({
            rootDir,
            logger: { ...createConsoleLogger(), warn: (message) => loggerWarnings.push(message) },
        })
        project.registerExplicitId('sys_ux_lib_asset', 'x_test/large', 'f881f04062524d3e9143ffaa4fdb746c')
        const output = await project.getOutput()
        const assetXmls = output.filter((x) => x.path.includes('sys_ux_lib_asset'))
        expect(loggerWarnings).toEqual([])
        expect(
            assetXmls.map((asset) => ({ path: path.basename(asset.path), content: asset.content }))
        ).toMatchSnapshot()
    })
    test('chunkData should preserve data integrity for very large strings', () => {
        // Create a string large enough to span multiple chunks (3+ chunks)
        // Each chunk is CHUNK_SIZE (933336), so create 3 * CHUNK_SIZE + some extra
        const largeString = 'X'.repeat(CHUNK_SIZE * 3 + 12345)

        // Split into chunks
        const chunks = chunkData(largeString)

        // Verify we got the expected number of chunks
        expect(chunks.length).toBe(4)

        // Verify chunk sizes
        expect(chunks[0]!.length).toBe(CHUNK_SIZE)
        expect(chunks[1]!.length).toBe(CHUNK_SIZE)
        expect(chunks[2]!.length).toBe(CHUNK_SIZE)
        expect(chunks[3]!.length).toBe(12345)

        // Re-concatenate chunks and verify they match the original
        const reconstructed = chunks.join('')
        expect(reconstructed).toBe(largeString)
        expect(reconstructed.length).toBe(largeString.length)
    })
