describe('chunkData', () => {
    test('should split and reconstruct data correctly across multiple chunks', () => {
        // Test with 2 chunks - minimal case to catch the substring bug
        const twoChunkData = 'A'.repeat(CHUNK_SIZE) + 'B'.repeat(1000)
        const twoChunks = chunkData(twoChunkData)
        expect(twoChunks.join('')).toBe(twoChunkData)

        // Test with 3+ chunks - ensure it scales
        const multiChunkData = 'X'.repeat(CHUNK_SIZE * 3 + 12345)
        const multiChunks = chunkData(multiChunkData)
        expect(multiChunks.join('')).toBe(multiChunkData)
    })

    test('should handle single chunk correctly', () => {
        const smallData = 'test data'
        const chunks = chunkData(smallData)
        expect(chunks.join('')).toBe(smallData)
    })
})

describe('sys_ux_lib_asset toFile with source artifact M2M', () => {
    // These tests cover the behaviour introduced when sourceArtifactRelationships
    // were added to sys_ux_lib_asset: the asset XML now embeds the M2M record
    // linking the asset to its sn_glider_source_artifact via mainRecord.with(...m2mRecords).
    //
    // The test app at apps/byoui-asset-m2m has:
    //   dist/static/app.jsdbx       — compiled JS (creates sys_ux_lib_asset x_test/app)
    //   dist/static/app.jsdbx.map   — source map (creates sys_ux_lib_asset x_test/app.js.map)
    //   dist/static/index.ui-source-manifest.json — manifest wiring HTML → JS entry
    //   client/index.html            — the HTML file imported by UiPage
    //
    // When a UiPage Fluent file referencing this HTML is built, ui-page-plugin calls
    // createAssetArtifactM2mRecord to register a dummy sys_ux_lib_asset + M2M per asset.
    // static-content-plugin then picks up those M2Ms via sourceArtifactRelationships and
    // embeds them into each asset XML in toFile.

    const rootDir = path.resolve(__dirname, 'apps', 'byoui-asset-m2m')

    // Helper that builds a project with a UiPage and returns all XML output.
    const buildWithUiPage = async (scope = 'x_test', includeSourceMap = true) => {
        const project = createProject({
            rootDir,
            config: { scope, clientDir: 'client' },
        })
        const pageId = project.registerExplicitId('sys_ui_page', 'byoui-m2m-test')
        const assetId = project.registerExplicitId('sys_ux_lib_asset', `${scope}/app`)
        const sourceMapId = includeSourceMap
            ? project.registerExplicitId('sys_ux_lib_asset', `${scope}/app.js.map`)
            : null

        project.addFile({
            path: 'src/fluent/byoui-m2m-test.now.ts',
            content: `
                import { UiPage } from '@servicenow/sdk/core'
                import _html from '../../client/index.html'
                UiPage({
                    $id: Now.ID['byoui-m2m-test'],
                    endpoint: '${scope}_byoui_m2m_test.do',
                    html: _html,
                })
            `,
        })

        const output = await project.getOutput()
        return { output, pageId, assetId, sourceMapId }
    }

    test('asset XML should embed the sn_glider_source_artifact_m2m record when one exists', async () => {
        const { output, assetId } = await buildWithUiPage()
        const assetXml = output.find((f) => f.path.includes(assetId))
        expect(assetXml).toBeDefined()
        expect(assetXml!.content).toContain('<sn_glider_source_artifact_m2m')
    })

    test('embedded M2M application_file should equal the sys_ux_lib_asset sys_id', async () => {
        const { output, assetId } = await buildWithUiPage()
        const assetXml = output.find((f) => f.path.includes(assetId))!
        const appFile = assetXml.content.match(/<application_file>([^<]+)<\/application_file>/)?.[1]
        expect(appFile).toBe(assetId)
    })

    test('embedded M2M source_artifact should equal the sn_glider_source_artifact sys_id', async () => {
        const { output, assetId, pageId } = await buildWithUiPage()

        // The artifact sys_id is embedded in the page XML
        const pageXml = output.find((f) => f.path.includes(pageId))!
        const artifactId = pageXml.content.match(
            /<sn_glider_source_artifact\s[^>]*>[\s\S]*?<sys_id>([^<]+)<\/sys_id>/
        )?.[1]
        expect(artifactId).toBeDefined()

        // The asset XML's M2M should reference the same artifact
        const assetXml = output.find((f) => f.path.includes(assetId))!
        const sourceArtifact = assetXml.content.match(/<source_artifact>([^<]+)<\/source_artifact>/)?.[1]
        expect(sourceArtifact).toBe(artifactId)
    })

    test('asset XML should not contain any sn_glider_source_artifact_m2m element when no M2M exists', async () => {
        // Build without a UiPage — no M2M is registered in the build database
        const project = createProject({
            rootDir,
            config: { clientDir: 'client' },
        })
        const assetId = project.registerExplicitId('sys_ux_lib_asset', 'x_test/app')
        // No UiPage Fluent file added — static-content-plugin runs but no M2M is created

        const output = await project.getOutput()
        const assetXml = output.find((f) => f.path.includes(assetId))
        expect(assetXml).toBeDefined()
        expect(assetXml!.content).not.toContain('sn_glider_source_artifact_m2m')
    })

    test('source-map asset gets its own M2M, not the JS entry M2M', async () => {
        const { output, assetId, sourceMapId } = await buildWithUiPage()

        const assetXml = output.find((f) => f.path.includes(assetId))!
        const sourceMapXml = output.find((f) => f.path.includes(sourceMapId!))!

        const assetAppFile = assetXml.content.match(/<application_file>([^<]+)<\/application_file>/)?.[1]
        const sourceMapAppFile = sourceMapXml.content.match(/<application_file>([^<]+)<\/application_file>/)?.[1]

        // Each asset contains only its own M2M (application_file = its own sys_id)
        expect(assetAppFile).toBe(assetId)
        expect(sourceMapAppFile).toBe(sourceMapId)

        // The two M2Ms reference different application_files
        expect(assetAppFile).not.toBe(sourceMapAppFile)

        // Both assets have exactly one M2M each
        expect([...assetXml.content.matchAll(/<sn_glider_source_artifact_m2m\s/g)]).toHaveLength(1)
        expect([...sourceMapXml.content.matchAll(/<sn_glider_source_artifact_m2m\s/g)]).toHaveLength(1)
    })
})
